inline static uint8_t get_forbid(int loc) {
    int lo=0,hi=NUM_FORBID-1;
    while(lo<=hi){int mid=(lo+hi)/2;if(kForbid[mid].loc<loc)lo=mid+1;else if(kForbid[mid].loc>loc)hi=mid-1;else return kForbid[mid].forbid;}
    return 0;
}
inline static int get_exit(int loc) {
    int lo=0,hi=NUM_FORBID-1;
    while(lo<=hi){int mid=(lo+hi)/2;if(kForbid[mid].loc<loc)lo=mid+1;else if(kForbid[mid].loc>loc)hi=mid-1;else return kExit[mid];}
    return -1;
}
inline static bool is_exit_cell(int loc) {
    for(int i=0;i<NUM_EXIT;i++)if(kExitCells[i]==loc)return true;
    return false;
}
inline static bool get_guide(int loc, uint8_t& pd) {
    int lo=0,hi=NUM_GUIDE-1;
    while(lo<=hi){int mid=(lo+hi)/2;if(kGuide[mid].loc<loc)lo=mid+1;else if(kGuide[mid].loc>loc)hi=mid-1;else{pd=kGuide[mid].penalize_dir;return true;}}
    return false;
}
inline static int get_guide_exit(int loc) {
    int lo=0,hi=NUM_GUIDE-1;
    while(lo<=hi){int mid=(lo+hi)/2;if(kGuide[mid].loc<loc)lo=mid+1;else if(kGuide[mid].loc>loc)hi=mid-1;else return kGuideExit[mid];}
    return -1;
}
inline static bool is_task_forbidden(int loc) {
    for(int i=0;i<NUM_TASK;i++)if(kTask[i]==loc)return true;
    return false;
}
inline static void init(){static bool once=false;if(!once){once=true;printf("ORZ_H: %d forbid, %d guide, %d task, %d exit\n",NUM_FORBID,NUM_GUIDE,NUM_TASK,NUM_EXIT);}}

inline bool is_highway_cell(int loc) {
    int lo=0,hi=NUM_FORBID; while(lo<hi){int m=(lo+hi)/2;if(kForbid[m].loc<loc)lo=m+1;else hi=m;} if(lo<NUM_FORBID&&kForbid[lo].loc==loc)return true;
    lo=0;hi=NUM_GUIDE; while(lo<hi){int m=(lo+hi)/2;if(kGuide[m].loc<loc)lo=m+1;else hi=m;} if(lo<NUM_GUIDE&&kGuide[lo].loc==loc)return true;
    lo=0;hi=NUM_TASK; while(lo<hi){int m=(lo+hi)/2;if(kTask[m]<loc)lo=m+1;else hi=m;} if(lo<NUM_TASK&&kTask[lo]==loc)return true;
    lo=0;hi=NUM_EXIT; while(lo<hi){int m=(lo+hi)/2;if(kExitCells[m]<loc)lo=m+1;else hi=m;} if(lo<NUM_EXIT&&kExitCells[lo]==loc)return true;
    return false;
}

